const limit=(x,n=160)=>typeof x==='string'?x.trim().slice(0,n):'';
const requireValue=(ok,message)=>{if(!ok)throw Object.assign(Error(message),{statusCode:400});};
const number=(x,name,allowZero=false)=>{requireValue(Number.isFinite(x)&&(allowZero?x>=0:x>0)&&x<1e10,`${name} must be a valid ${allowZero?'non-negative':'positive'} number.`);return x;};
export const FEATURES=['explain','transporter','documents'];
export function normalizeAIRequest(raw){
 requireValue(raw&&FEATURES.includes(raw.feature),'Unknown AI assistance feature.');
 const s=raw.snapshot;requireValue(s&&typeof s==='object','A shipment/plan snapshot is required.');
 requireValue(Array.isArray(s.lines)&&s.lines.length>0&&s.lines.length<=40,'Provide between one and forty shipment lines.');
 const lines=s.lines.map(l=>{const result={order:limit(l.order,60),sku:limit(l.sku,60),quantity:number(l.quantity,'Quantity'),unitWeight:number(l.unitWeight,'Packed weight'),unitVolume:number(l.unitVolume,'Packed volume'),unitValue:number(l.unitValue,'Goods value')};requireValue(Number.isInteger(result.quantity)&&result.order&&result.sku,'Order, SKU and whole-unit quantity are required.');return result;});
 const truck=s.truck;requireValue(truck&&limit(truck.name),'Truck details are required.');
 const snapshot={id:limit(s.id,80),principal:limit(s.principal),origin:limit(s.origin),destination:limit(s.destination),departure:limit(s.departure,10),route:limit(s.route),lines,truck:{name:limit(truck.name),capacity:number(truck.capacity,'Truck payload'),volume:number(truck.volume,'Truck volume'),freight:number(truck.freight,'Freight estimate',true)},documents:[],additionalCompatibleUnits:number(s.additionalCompatibleUnits||0,'Additional compatible units',true)};
 requireValue(snapshot.id&&snapshot.principal&&snapshot.origin&&snapshot.destination,'Shipment identity, principal, origin and destination are required.');
 requireValue(/^\d{4}-\d{2}-\d{2}$/.test(snapshot.departure),'Departure date is required.');
 if(raw.feature==='documents'){
  requireValue(Array.isArray(s.documents)&&s.documents.length<=6,'Document status is required.');snapshot.documents=s.documents.map(d=>{requireValue(['invoice','eway','lr','pod','approval'].includes(d.kind),'Unknown document type.');return {kind:d.kind,hasFile:d.hasFile===true,verified:d.verified===true,quantityMatches:d.quantityMatches===true};});
 }
 const documentText=raw.feature==='documents'?limit(raw.documentText,8000):'';requireValue(!/sk-(?:proj-)?[A-Za-z0-9_-]{16,}/.test(documentText),'Remove credentials from the document extract.');
 return {feature:raw.feature,snapshot,documentText};
}
export function aiFacts(request){
 const s=request.snapshot,qty=s.lines.reduce((n,l)=>n+l.quantity,0),weight=s.lines.reduce((n,l)=>n+l.quantity*l.unitWeight,0),volume=s.lines.reduce((n,l)=>n+l.quantity*l.unitVolume,0),value=s.lines.reduce((n,l)=>n+l.quantity*l.unitValue,0);
 const facts=[{id:'shipment',label:'Source plan / shipment',value:s.id},{id:'principal',label:'Principal',value:s.principal},{id:'origin',label:'Pickup warehouse',value:s.origin},{id:'destination',label:'Receiving destination',value:s.destination},{id:'departure',label:'Planned warehouse departure',value:s.departure},{id:'truck',label:'Selected truck',value:s.truck.name},{id:'quantity',label:'Planned / packed quantity',value:`${qty} units`},{id:'weight',label:'Gross packed weight',value:`${weight.toFixed(2)} kg / ${s.truck.capacity} kg payload`},{id:'volume',label:'Packed volume',value:`${volume.toFixed(4)} m3 / ${s.truck.volume} m3 capacity`},{id:'value',label:'Sample goods value',value:`INR ${value.toFixed(2)}`},{id:'freight',label:'Configured freight estimate',value:`INR ${s.truck.freight.toFixed(2)}`},{id:'freight_ratio',label:'Freight / goods value',value:value>0?`${(s.truck.freight/value*100).toFixed(1)}%`:'Unavailable'},{id:'weight_utilization',label:'Weight utilization',value:`${(weight/s.truck.capacity*100).toFixed(1)}%`},{id:'volume_utilization',label:'Volume utilization',value:`${(volume/s.truck.volume*100).toFixed(1)}%`},{id:'fit',label:'Capacity check',value:weight<=s.truck.capacity&&volume<=s.truck.volume?'Weight and volume fit; physical loading arrangement not certified':'Selected truck does not fit the load'},{id:'additional_compatible',label:'Other compatible ready quantities',value:`${s.additionalCompatibleUnits} units; review deadlines and rate assumptions before combining`}];
 if(s.additionalCompatibleUnits>0&&s.lines.every(l=>l.sku===s.lines[0].sku&&l.unitValue===s.lines[0].unitValue)){const combinedValue=value+s.additionalCompatibleUnits*s.lines[0].unitValue;facts.push({id:'consolidation_example',label:'Conditional consolidation calculation',value:`${qty+s.additionalCompatibleUnits} total units; INR ${combinedValue.toFixed(2)} goods; ${(s.truck.freight/combinedValue*100).toFixed(1)}% freight/goods ONLY if the same trip quote remains applicable and deadlines permit`});}if(request.feature==='documents')for(const d of s.documents)facts.push({id:'doc_'+d.kind,label:d.kind+' document status',value:!d.hasFile?'Missing retrievable file':!d.quantityMatches?'Recorded document quantity differs from current manifest':!d.verified?'Present; operator verification pending':'Present; current recorded quantity and human verification match; authenticity not independently established'});
 return facts;
}
export function localAssistance(request){const facts=aiFacts(request),s=request.snapshot;let summary,actions;
 if(request.feature==='transporter'){summary='Please arrange the selected vehicle for the warehouse departure shown below. Confirm availability and agreed freight before the operator proceeds.';actions=['Review the source details before sharing this draft.','Request vehicle and driver confirmation through your approved manual handoff.'];}
 else if(request.feature==='documents'){const gaps=facts.filter(f=>f.id.startsWith('doc_')&&!f.value.startsWith('Present; current'));summary=gaps.length?'Document gaps remain. Resolve the source checklist before dispatch.':'The recorded checklist is complete; this is not a legal-validity or authenticity certification.';actions=gaps.map(f=>f.label+': '+f.value);if(request.documentText)actions.push('Pasted document text is untrusted and has not been verified by the local fallback.');}
 else{const w=facts.find(f=>f.id==='weight_utilization'),v=facts.find(f=>f.id==='volume_utilization');summary='Review truck fit, utilization and freight relative to goods value before approving this departure plan.';actions=['Freight percentage describes cost relative to goods value; it is not truck fullness or a profit calculation.'];if(parseFloat(w.value)<20&&parseFloat(v.value)<20)actions.push('The load uses little of the selected truck. Review compatible consolidation without missing the agreed customer delivery deadline.');if(s.additionalCompatibleUnits>0)actions.push('Other compatible quantities are available for a human planning review.');}
 return {title:request.feature==='transporter'?'Transporter message draft':request.feature==='documents'?'Document-gap summary':'Shipment planning explanation',summary,actions,missing_information:['External carrier confirmation and actual delivery outcomes are not established by this request.'],fact_ids:facts.map(f=>f.id),review_required:true};
}
export const OUTPUT_SCHEMA={type:'object',additionalProperties:false,properties:{title:{type:'string'},summary:{type:'string'},actions:{type:'array',items:{type:'string'}},missing_information:{type:'array',items:{type:'string'}},fact_ids:{type:'array',items:{type:'string'}},review_required:{type:'boolean'}},required:['title','summary','actions','missing_information','fact_ids','review_required']};
export function validateAssistance(value,facts,documentText=''){
 requireValue(value&&typeof value==='object'&&!Array.isArray(value),'AI returned an invalid object.');
 requireValue(Object.keys(value).every(k=>Object.keys(OUTPUT_SCHEMA.properties).includes(k)),'AI returned unsupported fields.');
 for(const key of ['title','summary'])requireValue(typeof value[key]==='string'&&value[key].trim()&&value[key].length<5000,'AI response has invalid text.');
 for(const key of ['actions','missing_information','fact_ids'])requireValue(Array.isArray(value[key])&&value[key].length<=20&&value[key].every(x=>typeof x==='string'&&x.length<=1500),'AI response has invalid lists.');
 requireValue(value.review_required===true,'AI cannot remove operator review.');const ids=new Set(facts.map(f=>f.id));requireValue(value.fact_ids.every(id=>ids.has(id)),'AI cited a fact that was not supplied.');
 const text=[value.title,value.summary,...value.actions,...value.missing_information].join(' ');const supplied=facts.map(f=>f.value).join(' ')+' '+documentText;const tokens=str=>(str.match(/\d+(?:[.,]\d+)*/g)||[]).map(x=>Number(x.replaceAll(',',''))).filter(Number.isFinite);const permitted=new Set(tokens(supplied));
 requireValue(tokens(text).every(n=>permitted.has(n)),'AI introduced an unsupported number. Review the verified facts instead.');
 requireValue(!/(?:successfully (?:sent|booked|dispatched)|I (?:have )?(?:sent|booked|dispatched)|dispatch is approved)/i.test(text),'AI claimed an unauthorized operational action.');return value;
}
